<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class Membellishment extends CI_Controller {    public function __construct() {        parent::__construct();        fnIfCheckUserLoggedIn();        $this->load->model(CNFCOMPANY . "membellishmenttypemodel");        $this->load->model(CNFCOMPANY . "mmediummaterialmodel");        $this->load->helper('xssclean');        $VarUserInfo = fnGetUserLoggedInfo(1);        if (isset($VarUserInfo['companyid'])) {            $this->companyid = $VarUserInfo['companyid'];        }        $this->limit = LIMITPERPAGE;    }    public function addeditmediummaterial() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '','ArrStatus'=>unserialize(ARRSTATUS));        $VarId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarId <> '' && base64_decode(urldecode($VarId))) {            $VarUserId = base64_decode(urldecode($VarId));            $ArrResults = $this->mmediummaterialmodel->fnGetMediumMaterialInfo('', '', $VarUserId);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditemediummaterial', $ArrData);    }    public function addeditembellishmenttype() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '','ArrStatus'=>unserialize(ARRSTATUS));        $VarId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarId <> '' && base64_decode(urldecode($VarId))) {            $VarUserId = base64_decode(urldecode($VarId));            $ArrResults = $this->membellishmenttypemodel->fnGetInfo('', '', $VarUserId);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditembelltype', $ArrData);    }    public function updateMediumMaterialInfo() {        $ArrResult = array();        $VarUserLoggedInfo = fnGetUserLoggedInfo(1);        $VarMedium = xssclean($this->input->post('m'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarMedium <> '') {            $ArrUpdateData = array('id' => $VarId, 'medium_material' => $VarMedium, 'companyid' => $VarUserLoggedInfo['companyid'],                'status' => $VarStatus, 'updatedby' => $VarUserLoggedInfo['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mmediummaterialmodel->saveMediumMaterial($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function updateEmbellishmentInfo() {        $ArrResult = array();        $VarUserLoggedInfo = fnGetUserLoggedInfo(1);        $VarEmbellName = xssclean($this->input->post('en'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarEmbellName <> '') {            $ArrUpdateData = array('id' => $VarId, 'embellname' => $VarEmbellName, 'companyid' => $VarUserLoggedInfo['companyid'],                'status' => $VarStatus, 'updatedby' => $VarUserLoggedInfo['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->membellishmenttypemodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manageMediumMaterial() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarMm =trim(xssclean($this->input->post('mm')));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarClass = $this->router->class;        $VarMethod = $this->router->method;        $ArrStatus = unserialize(ARRSTATUS);        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . $VarClass.'/'.$VarMethod;            $config['total_rows'] = $this->mmediummaterialmodel->fnCountMediumMaterial($VarMm, $VarStatus,$this->companyid);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "e.dateupdated";            $sortorder = "desc";            $ArrDbCols = array('medium_material', 'm.status', 'updatedby', 'm.dateupdated');            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->mmediummaterialmodel->fnListMediumMaterial($VarMm, $VarStatus, $this->companyid,$this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('MedMaterial');            $i = 0;            $ArrFnlList = array();            foreach ($ArrList as $Obj) {                $ArrFnlList[$i]['id'] = $Obj->id;                $ArrFnlList[$i]['mm'] = $Obj->medium_material;                $ArrFnlList[$i]['ub'] = $Obj->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$Obj->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i A', strtotime($Obj->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managemedmaterial',array('ArrStatus'=>$ArrStatus));        }    }    public function manageType() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarMm = trim(xssclean($this->input->post('em')));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarClass = $this->router->class;        $VarMethod = $this->router->method;        $ArrStatus = unserialize(ARRSTATUS);        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . $VarClass.'/'.$VarMethod;            $config['total_rows'] = $this->membellishmenttypemodel->fnCount($VarMm, $VarStatus,$this->companyid);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "e.dateupdated";            $sortorder = "desc";            $ArrDbCols = array('embellname', 'm.status', 'updatedby', 'm.dateupdated');            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->membellishmenttypemodel->fnList($VarMm, $VarStatus, $this->companyid,$this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('EmbellType');            $i = 0;            $ArrFnlList = array();            foreach ($ArrList as $Obj) {                $ArrFnlList[$i]['id'] = $Obj->id;                $ArrFnlList[$i]['em'] = $Obj->embellname;                $ArrFnlList[$i]['ub'] = $Obj->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$Obj->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i A', strtotime($Obj->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'manageembelltype',array('ArrStatus'=>$ArrStatus));        }    }    function changeMedMaterialStatus() {        $VarStatus = xssclean($this->input->post('status'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarStatus <> '' && $VarCid <> '') {            $this->mmediummaterialmodel->changeMedMaterialStatus($VarCid, $VarStatus);        }        echo json_encode(array('errcode' => 1));        die;    }    function changeEmbellishmentType() {        $VarStatus = xssclean($this->input->post('status'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarStatus <> '' && $VarCid <> '') {            $this->membellishmenttypemodel->changeStatus($VarCid, $VarStatus);        }        echo json_encode(array('errcode' => 1));        die;    }}